```typescript
import { test, expect } from '@playwright/test';

test.describe('Account Lockout After Failed Login Attempts', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'correctPassword123',
    incorrectPassword: 'wrongPassword123'
  };

  const loginUrl = 'http://localhost:3000/login';
  const maxFailedAttempts = 5;

  test.beforeEach(async ({ page }) => {
    await page.goto(loginUrl);
  });

  test('should lock account after 5 failed login attempts', async ({ page }) => {
    // Attempt to login 5 times with incorrect password
    for (let i = 1; i <= maxFailedAttempts; i++) {
      // Fill in email
      await page.getByLabel(/email/i).fill(testUser.email);

      // Fill in incorrect password
      await page.getByLabel(/password/i).fill(testUser.incorrectPassword);

      // Click login button
      await page.getByRole('button', { name: /login/i }).click();

      // Wait for error message to appear
      await page.getByText(/invalid credentials|incorrect password/i).waitFor({ timeout: 5000 });

      // Verify attempt counter or error message shows current attempt
      if (i < maxFailedAttempts) {
        const errorMessage = await page.getByText(new RegExp(`attempt ${i}|${i} failed`, 'i')).isVisible().catch(() => false);
        if (errorMessage) {
          expect(errorMessage).toBeTruthy();
        }
      }

      // Clear fields for next attempt
      await page.getByLabel(/email/i).clear();
      await page.getByLabel(/password/i).clear();
    }

    // Verify account is locked after 5 failed attempts
    const lockedMessage = page.getByText(/account locked|too many failed attempts|account has been locked/i);
    await lockedMessage.waitFor({ timeout: 5000 });
    expect(await lockedMessage.isVisible()).toBeTruthy();

    // Verify login button is disabled or form is disabled
    const loginButton = page.getByRole('button', { name: /login/i });
    const isDisabled = await loginButton.isDisabled().catch(() => false);
    const isHidden = await loginButton.isHidden().catch(() => false);

    expect(isDisabled || isHidden).toBeTruthy();
  });

  test('should display warning message before account lockout', async ({ page }) => {
    // Attempt to login 4 times with incorrect password
    for (let i = 1; i <= 4; i++) {
      await page.getByLabel(/email/i).fill(testUser.email);
      await page.getByLabel(/password/i).fill(testUser.incorrectPassword);
      await page.getByRole('button', { name: /login/i }).click();

      // Wait for error message
      await page.getByText(/invalid credentials|incorrect password/i).waitFor({ timeout: 5000 });

      // Verify warning message about remaining attempts
      const warningMessage = page.getByText(new RegExp(`${maxFailedAttempts - i} attempt|remaining`, 'i'));
      const isVisible = await warningMessage.isVisible().catch(() => false);

      if (isVisible) {
        expect(isVisible).toBeTruthy();
      }

      await page.getByLabel(/email/i).clear();
      await page.getByLabel(/password/i).clear();
    }

    // On 5th attempt, verify final warning before lockout
    await page.getByLabel(/email/i).fill(testUser.email);
    await page.getByLabel(/password/i).fill(testUser.incorrectPassword);
    await page.getByRole('button', { name: /login/i }).click();

    // Verify account is now locked
    const lockedMessage = page.getByText(/account locked|too many failed attempts/i);
    await lockedMessage.waitFor({ timeout: 5000 });
    expect(await lockedMessage.isVisible()).toBeTruthy();
  });

  test('should not lock account with correct password after failed attempts', async ({ page }) => {
    // Attempt to login 3 times with incorrect password
    for (let i = 1; i <= 3; i++) {
      await page.getByLabel(/email/i).fill(testUser.email);
      await page.getByLabel(/password/i).fill(testUser.incorrectPassword);
      await page.getByRole('button', { name: /login/i }).click();

      await page.getByText(/invalid credentials|incorrect password/i).waitFor({ timeout: 5000 });

      await page.getByLabel(/email/i).clear();
      await page.getByLabel(/password/i).clear();
    }

    // Now attempt with correct password
    await page.getByLabel(/email/i).fill(testUser.email);
    await page.getByLabel(/password/i).fill(testUser.password);
    await page.getByRole('button', { name: /login/i }).click();

    // Verify successful login - should redirect or show success message
    const successIndicator = page.getByText(/welcome|dashboard|login successful/i);
    const urlChanged = page.url() !== loginUrl;

    const isSuccessful = await successIndicator.isVisible().catch(() => false) || urlChanged;
    expect(isSuccessful).toBeTruthy();
  });

  test('should reset failed attempt counter on successful login', async ({ page }) => {
    // Attempt to login 2 times with incorrect password
    for (let i = 1; i <= 2; i++) {
      await page.getByLabel(/email/i).fill(testUser.email);
      await page.getByLabel(/password/i).fill(testUser.incorrectPassword);
      await page.getByRole('button', { name: /login/i }).click();

      await page.getByText(/invalid credentials|incorrect password/i).waitFor({ timeout: 5000 });

      await page.getByLabel(/email/i).clear();
      await page.getByLabel(/password/i).clear();
    }

    // Login successfully
    await page.getByLabel(/email/i).fill(testUser.email);
    await page.getByLabel(/password/i).fill(testUser.password);
    await page.getByRole('button', { name: /login/i }).click();

    // Verify successful login
    const successIndicator = page.getByText(/welcome|dashboard|login successful/i);
    const urlChanged = page.url() !== loginUrl;
    expect(await successIndicator.isVisible().catch(() => false) || urlChanged).toBeTruthy();

    // Logout
    const logoutButton = page.getByRole('button', { name: /logout|sign out/i });
    if (await logoutButton.isVisible().catch(() => false)) {
      await logoutButton.click();
    }

    // Navigate back to login
    await page.goto(loginUrl);

    // Attempt to login with incorrect password - should allow multiple attempts again
    for (let i = 1; i <= 3; i++) {
      await page.getByLabel(/email/i).fill(testUser.email);
      await page.getByLabel(/password/i).fill(testUser.incorrectPassword);
      await page.getByRole('button', { name: /login/i }).click();

      await page.getByText(/invalid credentials|incorrect password/i).waitFor({ timeout: 5000 });

      // Verify account is not locked yet
      const lockedMessage = page.getByText(/account locked/i);
      expect(await lockedMessage.isVisible().catch(() => false)).toBeFalsy();

      await page.getByLabel(/email/i).clear();
      await page.getByLabel(/password/i).clear();
    }
  });
});
